import{_ as t,o as a,c as o,a0 as s}from"./chunks/framework.ChlVJx0I.js";const n="/pi-extensions/assets/quota-detail.By4iFBeW.png",i="/pi-extensions/assets/quota-footer.CveqHqo2.png",m=JSON.parse('{"title":"quota extension","description":"","frontmatter":{},"headers":[],"relativePath":"extensions/quota.md","filePath":"extensions/quota.md","lastUpdated":1789775493000}'),r={name:"extensions/quota.md"};function l(d,e,h,c,u,p){return a(),o("div",null,[...e[0]||(e[0]=[s('<h1 id="quota-extension" tabindex="-1">quota extension <a class="header-anchor" href="#quota-extension" aria-label="Permalink to &quot;quota extension&quot;">​</a></h1><p>Monitors the OpenAI ChatGPT plan quota, so the user sees the remaining budget before a 5-hour or weekly limit is hit mid-task. A footer line always shows the plan&#39;s quota windows as used percentages; <code>/quota</code> forces a fresh read and shows the detail view (plan type, account email, reset times, time left, last fetched).</p><p>Works from any session. It reads the quota through the Quota source module (<code>source.ts</code>), which owns all data logic and the ChatGPT token refresh (<a href="/pi-extensions/adr/0005-quota-owns-chatgpt-token-refresh.html">ADR 0005</a>). The <a href="/pi-extensions/extensions/model-router.html">model-router</a> extension reuses the same module.</p><h2 id="screenshots" tabindex="-1">Screenshots <a class="header-anchor" href="#screenshots" aria-label="Permalink to &quot;Screenshots&quot;">​</a></h2><p>The detail view (<code>/quota</code>) with the fixture snapshot:</p><p><img src="'+n+'" alt="quota detail view"></p><p>The footer line in the status bar:</p><p><img src="'+i+`" alt="quota footer line"></p><h2 id="behavior" tabindex="-1">Behavior <a class="header-anchor" href="#behavior" aria-label="Permalink to &quot;Behavior&quot;">​</a></h2><ul><li><strong>Footer line.</strong> <code>GPT 5h 42% · 7d 18%</code> in the status bar. An exhausted window reads <code>FULL</code> in the error color. Windows are labeled by their length: <code>5h</code> and <code>7d</code> on the ChatGPT plans, <code>30d</code> on the free plan. Reset times never appear in the footer.</li><li><strong>Freshness.</strong> The quota is read once at session start, then every 5 minutes while the session runs. The interval is a fixed constant; there is no setting for it.</li><li><strong><code>/quota</code>.</strong> Forces a fresh read and shows the detail view: plan type, account email, each window with its reset time and time left, and the last fetched time.</li><li><strong>Stale numbers.</strong> A failed read keeps the last good snapshot, marked <code>stale</code> in the footer and in the detail view, instead of hiding the numbers.</li><li><strong>Failure noise.</strong> The first failure of a run raises one error notification; repeated failures while polling are silent. A new failure reason raises one notification of its own. A dead login is told with a re-login error instead.</li><li><strong>Token refresh.</strong> The access token comes from pi&#39;s own auth store (<code>openai-codex</code> OAuth entry). When it is expired, or a usage fetch 401s, the module refreshes it through the same token endpoint and client id pi&#39;s bundled OAuth uses, writes the rotated pair back to the auth store, and retries once after re-reading. A failed refresh declares the login dead. A re-login is picked up on the next poll without restarting pi.</li><li><strong>No login, no output.</strong> Without an <code>openai-codex</code> login the extension is invisible: no footer line, no notifications.</li><li><strong>Non-TUI modes.</strong> Print and JSON modes never see quota output: the UI calls are guarded, so scripted output is unaffected.</li></ul><h2 id="quota-detail-view" tabindex="-1"><code>/quota</code> detail view <a class="header-anchor" href="#quota-detail-view" aria-label="Permalink to &quot;\`/quota\` detail view&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>ChatGPT plan quota</span></span>
<span class="line"><span>Plan: plus</span></span>
<span class="line"><span>Account: julian@example.com</span></span>
<span class="line"><span></span></span>
<span class="line"><span>5h  42%   resets 19:00 (in 5h)</span></span>
<span class="line"><span>7d  18%   resets Thu 14:00 (in 7d)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Fetched: 13:56:00 (4m ago)</span></span></code></pre></div><p>An exhausted window&#39;s line reads <code>FULL</code> in the error color. A stale snapshot adds one line saying the numbers are the last good ones.</p><h2 id="data-source" tabindex="-1">Data source <a class="header-anchor" href="#data-source" aria-label="Permalink to &quot;Data source&quot;">​</a></h2><p>The usage endpoint (<code>GET https://chatgpt.com/backend-api/wham/usage</code>) is not a documented public API. Response shape drift is a supported failure (stale snapshot plus one error), not a crash. Credits, promo, and additional-limit buckets from the response are not shown.</p><h2 id="out-of-scope" tabindex="-1">Out of scope <a class="header-anchor" href="#out-of-scope" aria-label="Permalink to &quot;Out of scope&quot;">​</a></h2><ul><li>The Qwen token plan (its usage API is browser-cookie only). A second plan goes behind the same Quota source seam (<code>source.ts</code>).</li><li>An agent tool for the LLM to query its own quota.</li><li>API-key (pay-as-you-go) spend and credit-balance tracking.</li></ul><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li><code>tests/quota/source.test.ts</code> - the Quota source seam: fake fetch and a temp auth file, no network.</li><li><code>tests/quota/render.test.ts</code> - footer and detail strings.</li><li><code>npm run e2e:quota</code> - a real pi RPC session against the live endpoint; needs a working openai-codex login.</li></ul>`,19)])])}const g=t(r,[["render",l]]);export{m as __pageData,g as default};
